import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
}

const startOfDay = (date: Date) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() - days);
  return base;
};

const presets = [
  { key: 'today', label: 'Сегодня', days: 0 },
  { key: 'yesterday', label: 'Вчера', days: 1 },
  { key: 'week', label: 'Неделя назад', days: 7 },
];

export default function ReportDatePicker({ defaultValue = null, onChange }: ReportDatePickerProps) {
  const [value, setValue] = useState<Date | null>(
    defaultValue ? startOfDay(defaultValue) : null,
  );

  const select = (next: Date | null) => {
    const normalized = next ? startOfDay(next) : null;
    setValue(normalized);
    onChange?.(normalized);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {presets.map((preset) => {
          const presetDate = shiftDays(preset.days);
          return (
            <JxChip
              key={preset.key}
              active={value?.getTime() === presetDate.getTime()}
              onClick={() => select(presetDate)}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>

      <JxCalendar locale="ru-RU" value={value} onValueChange={select} />

      <span style={{ color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-sans)', fontSize: '13px' }}>
        {value ? value.toLocaleDateString('ru-RU') : 'Дата не выбрана'}
      </span>
    </div>
  );
}

